import{_ as o,c as t,o as d,am as a}from"./chunks/framework.BJtUKP3U.js";const u=JSON.parse('{"title":"文件图标提示气泡","description":"","frontmatter":{"prev":{"text":"Pogget_Std 字段表","link":"/docs/pogget/custom-vina/standard-fields"},"next":{"text":"宿主输入","link":"/docs/pogget/custom-vina/inputs"}},"headers":[],"relativePath":"docs/pogget/custom-vina/tooltips.md","filePath":"docs/pogget/custom-vina/tooltips.md"}'),c={name:"docs/pogget/custom-vina/tooltips.md"};function s(n,e,i,p,l,r){return d(),t("div",null,e[0]||(e[0]=[a(`<h1 id="文件图标提示气泡" tabindex="-1">文件图标提示气泡 <a class="header-anchor" href="#文件图标提示气泡" aria-label="Permalink to &quot;文件图标提示气泡&quot;">​</a></h1><p>标准预设的 <code>FileTooltip</code> 组件控制文件图标悬停提示的布局、背景、文字、裁剪及显示策略。它使用 <code>slot: &quot;fileTooltip&quot;</code>，仍在整盒 <code>containerFrame</code> 之后、标题标签和工具栏自身的提示之前绘制。<code>z</code> 只调整阶段内部的顺序。</p><p>默认外观沿用原有实现：600ms 后开始显示，200ms 线性淡入，离开时 200ms 淡出，拖动时 150ms 淡出；逻辑宽度或高度小于 200 DIP 时采用紧凑布局，并在首次绘制时锁定鼠标锚点。普通布局跟随图标位置，电脑、网络、回收站、控制面板默认不显示文件提示。背景保留原有的不透明填充及随进度改变宽度的边框，文字和阴影按进度变化。</p><p>宿主继续负责悬停判定、取消计时器、拖动/折叠/销毁清理、文件信息及 DirectWrite 测量。提示装饰应保持被动，不设置 <code>action</code>、<code>holdAction</code> 或 <code>toggle</code>。其他控件的提示不属于这个阶段。缺少此 slot 的旧独立预设继续使用原生文件提示；依赖标准预设时直接覆盖 <code>FileTooltip</code>。</p><h2 id="调整外观和显示时间" tabindex="-1">调整外观和显示时间 <a class="header-anchor" href="#调整外观和显示时间" aria-label="Permalink to &quot;调整外观和显示时间&quot;">​</a></h2><p>以下是可以直接保存的依赖预设。它只覆盖列出的字段，其余保留标准行为。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Preset { dependsOn: &quot;Pogget_Std&quot; }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>FileTooltip {</span></span>
<span class="line"><span>  vars { maxWidth: 340, radius: 10, fontSize: 13 },</span></span>
<span class="line"><span>  view {</span></span>
<span class="line"><span>    tooltip { delay: 350ms, fadeIn: 120ms },</span></span>
<span class="line"><span>    Surface { background: rgb(30, 42, 56) }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>常用变量位于 <code>FileTooltip.vars</code>：<code>maxWidth</code> 最大宽度（默认 280），<code>font</code> 字体，<code>fontSize</code> 字号，<code>padding</code> 横向留白，<code>top</code>/<code>bottom</code> 纵向留白，<code>line</code> 行距，<code>radius</code> 圆角，<code>inset</code> 到窗口边缘的距离。<code>width</code>/<code>height</code>/<code>x</code>/<code>y</code> 是标准布局公式，也可以覆盖。直接覆盖文字字体或字号时，应同步修改下面的测量策略。</p><h2 id="tooltip-策略" tabindex="-1">tooltip 策略 <a class="header-anchor" href="#tooltip-策略" aria-label="Permalink to &quot;tooltip 策略&quot;">​</a></h2><p>元数据写在 <code>FileTooltip.view.tooltip</code>。下表的默认值是独立声明时的默认；标准预设会根据窗口大小覆盖其中的三个字段。</p><table tabindex="0"><thead><tr><th>字段</th><th>类型、默认值与含义</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>布尔，<code>true</code>；是否允许启动和显示文件提示；禁用会取消当前悬停的计时/淡入，重新启用后按当前延迟启动</td></tr><tr><td><code>paintEnabled</code></td><td>布尔，<code>true</code>；仅控制绘制及文件信息读取，保留计时进度；标准在可用宽度小于 8 或高度小于 12 DIP 时关闭</td></tr><tr><td><code>showSpecial</code></td><td>布尔，<code>false</code>；允许电脑、网络、回收站、控制面板等特殊项目显示提示</td></tr><tr><td><code>delay</code></td><td>数值，默认 <code>600ms</code>；进入悬停后的延迟；<code>0</code> 立即开始</td></tr><tr><td><code>fadeIn</code></td><td>数值，默认 <code>200ms</code>；淡入时间</td></tr><tr><td><code>fadeOut</code></td><td>数值，默认 <code>200ms</code>；离开后的淡出时间</td></tr><tr><td><code>dragFadeOut</code></td><td>数值，默认 <code>150ms</code>；拖动开始后的淡出时间</td></tr><tr><td><code>pointerAnchor</code></td><td>布尔，<code>false</code>；使用鼠标锚点；标准紧凑布局为 <code>true</code></td></tr><tr><td><code>followPointer</code></td><td>布尔，<code>false</code>；启用鼠标锚点后，每次绘制更新锚点；关闭则在首次有效绘制时锁定</td></tr><tr><td><code>showMetadata</code></td><td>布尔，<code>true</code>；是否读取大小和修改时间；标准紧凑布局为 <code>false</code>；文本节点的可见性也应跟随此字段</td></tr><tr><td><code>font</code></td><td>非空文本，默认 <code>&quot;Segoe UI&quot;</code>，最长 128 个 UTF-16 单元；文字测量字体</td></tr><tr><td><code>textSize</code></td><td>数值，默认 <code>12</code>，范围 <code>1..256</code> DIP；文字测量字号</td></tr><tr><td><code>textWidth</code></td><td>数值，默认 <code>1</code>，范围 <code>1..32768</code> DIP；测量文件名换行的实际可用宽度，标准自动使用 <code>vars.textWidth</code></td></tr></tbody></table><p>所有时间范围为 <code>0..10</code> 秒；<code>350ms</code> 等于 <code>0.35</code>。布尔字段只接受 <code>true</code>/<code>false</code> 或布尔表达式。计时参数在启动对应计时/动画时读取，修改时长不会重写已运行的动画；当前悬停的 <code>enabled</code> 变化会在重绘时重新协调。非法实时策略跳过该提示，不复用另一个图标的布局。</p><p>策略在计时前也会求值；此时文件信息文本和测量结果尚不可用，不应据此定义 <code>enabled</code>、延迟或测量字体。宿主先测量三段文字宽度，再读取 <code>textWidth</code> 测量换行数，最后更新视图。用独立输入定义字体和字号，避免让测量参数反向依赖自己的测量结果。</p><h2 id="提示上下文-pogget-tooltip" tabindex="-1">提示上下文 pogget.tooltip <a class="header-anchor" href="#提示上下文-pogget-tooltip" aria-label="Permalink to &quot;提示上下文 pogget.tooltip&quot;">​</a></h2><p>这些输入描述本次处理的提示。长度和坐标均为 DIP，数值是只读事实。</p><table tabindex="0"><thead><tr><th>输入</th><th>类型与含义</th></tr></thead><tbody><tr><td><code>path</code></td><td>文本；当前提示项目的完整路径或原生图标标识，淡出期间仍保留</td></tr><tr><td><code>name</code></td><td>文本；当前文件名；无法提取名称时使用路径</td></tr><tr><td><code>sizeText</code>、<code>modifiedText</code></td><td>文本；宿主已格式化的大小/文件夹及修改时间，仅显示并启用信息读取时有效</td></tr><tr><td><code>alpha</code></td><td>数值，<code>0..1</code>；提示的显示进度</td></tr><tr><td><code>iconX</code>、<code>iconY</code>、<code>iconWidth</code>、<code>iconHeight</code></td><td>数值；图标当前交互矩形的位置及尺寸</td></tr><tr><td><code>viewportWidth</code>、<code>viewportHeight</code></td><td>数值；窗口客户区逻辑宽高</td></tr><tr><td><code>mouseX</code>、<code>mouseY</code></td><td>数值；当前鼠标客户区位置，应配合 <code>hasMouse</code> 使用</td></tr><tr><td><code>anchorX</code>、<code>anchorY</code></td><td>数值；锁定或跟随后的鼠标锚点；尚未锁定时使用当前鼠标位置</td></tr><tr><td><code>hasMouse</code></td><td>布尔；鼠标坐标是否有效</td></tr><tr><td><code>special</code></td><td>布尔；是否为默认排除的特殊图标</td></tr><tr><td><code>nameWidth</code>、<code>sizeWidth</code>、<code>modifiedWidth</code></td><td>数值；按测量字体和字号得到的三段文字宽度</td></tr><tr><td><code>wrappedLines</code></td><td>数值，至少 <code>1</code>；文件名按 <code>textWidth</code> 排版后的行数</td></tr></tbody></table><p>实际引用要包含完整前缀，例如 <code>\${pogget.tooltip.path}</code>。这些不是所有图标的查询接口。提示图片请使用 <code>tooltip.path</code>；<code>\${pogget.hoveredIcon.path}</code> 在鼠标离开后会清空，而旧提示可能仍在淡出。</p><h2 id="用-matches-筛选图片并显示缩略图" tabindex="-1">用 matches 筛选图片并显示缩略图 <a class="header-anchor" href="#用-matches-筛选图片并显示缩略图" aria-label="Permalink to &quot;用 matches 筛选图片并显示缩略图&quot;">​</a></h2><p><code>matches(text, &quot;pattern&quot;[, &quot;i&quot;])</code> 返回布尔值。以下完整预设在图片上显示预览，其他文件继续使用标准文字提示。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Preset { dependsOn: &quot;Pogget_Std&quot; }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>FileTooltip {</span></span>
<span class="line"><span>  vars {</span></span>
<span class="line"><span>    preview: matches(\${pogget.tooltip.path}, &quot;\\\\.(png|jpe?g|webp|gif|bmp|avif|jfif)$&quot;, &quot;i&quot;),</span></span>
<span class="line"><span>    width: \${vars.preview} ? min(176,\${vars.availableW}) : max(1,min(min(\${vars.maxWidth},\${vars.availableW}),\${vars.contentWidth}+\${vars.padding}*2+2)),</span></span>
<span class="line"><span>    height: \${vars.preview} ? min(152,\${vars.availableH}) : min(\${vars.availableH},\${vars.fixedHeight}+\${vars.nameHeight})</span></span>
<span class="line"><span>  },</span></span>
<span class="line"><span>  view {</span></span>
<span class="line"><span>    tooltip { showMetadata: !\${FileTooltip.vars.preview} &amp;&amp; !\${FileTooltip.vars.compact} },</span></span>
<span class="line"><span>    Text { visible: !\${FileTooltip.vars.preview} },</span></span>
<span class="line"><span>    Preview {</span></span>
<span class="line"><span>      type: &quot;image&quot;, imageRenderer: &quot;wic&quot;, preferThumbnail: true,</span></span>
<span class="line"><span>      visible: \${FileTooltip.vars.preview}, source: \${pogget.tooltip.path},</span></span>
<span class="line"><span>      x: 8, y: 8,</span></span>
<span class="line"><span>      width: max(1,\${FileTooltip.vars.width}-16), height: max(1,\${FileTooltip.vars.height}-16),</span></span>
<span class="line"><span>      imageFit: &quot;contain&quot;, opacity: \${pogget.tooltip.alpha}</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>扩展名匹配不保证系统安装了该格式的 WIC 解码器。加载中或失败时图片暂不绘制。<code>preferThumbnail: true</code> 显式选择现有异步缩略图服务，保持比例且最长边不超过 128 像素，适合小预览；默认 <code>false</code> 保留完整 WIC 图片。服务优先使用内嵌缩略图，再尝试解码器缩小解码，最后在后台缩放，不会在界面线程同步回退到完整图片。部分解码器仍可能在后台读取完整帧，不能保证所有格式都减少底层解码工作。Shell 和资源后端不受此开关影响。</p><h3 id="matches-语法与限制" tabindex="-1">matches 语法与限制 <a class="header-anchor" href="#matches-语法与限制" aria-label="Permalink to &quot;matches 语法与限制&quot;">​</a></h3><ul><li>第一参数必须是文本表达式；pattern 和 flags 必须是字符串字面量，编译时校验并共享相同规则。</li><li>默认查找任意匹配子串且区分大小写；<code>&quot;i&quot;</code> 只忽略 ASCII 大小写。<code>^</code>/<code>$</code> 表示整个文本的首尾，不按行匹配。</li><li>支持 Unicode 字面量、<code>.</code>、分组 <code>()</code>、或 <code>|</code>、<code>*</code>/<code>+</code>/<code>?</code>、字符组及范围（如 <code>[a-z]</code>、<code>[^0-9]</code>）、转义标点、<code>\\d</code>、<code>\\w</code>、<code>\\s</code>、<code>\\b</code>。<code>.</code> 不匹配回车或换行；<code>\\w</code> 和单词边界按 ASCII 字母、数字、下划线判定；<code>\\s</code> 为制表符至回车及空格。</li><li>不支持前后查找、反向引用、惰性量词、<code>{m,n}</code> 或其他 flags；不支持的写法会报错。</li><li>单个规则最多 512 个 UTF-16 单元、512 个编译状态，分组深度最多 32；一份合成预设最多 128 个不同规则；输入文本最多 32768 个 UTF-16 单元。</li><li>使用有界状态机，没有递归回溯；编译结果在不可变文档中共享，匹配状态使用固定存储。非法语法拒绝候选预设，非法实时输入沿用通用的上一有效帧机制。</li></ul><p><code>.vina</code> 字符串自身需要转义反斜杠，因此正则中的 <code>\\.</code> 写成 <code>&quot;\\\\.&quot;</code>。若外层再包 JSON 字符串，还需要再转义一次。以上代码块已经是可以直接保存到 <code>.vina</code> 的形式。</p><h2 id="visible-false-的性能边界" tabindex="-1">visible: false 的性能边界 <a class="header-anchor" href="#visible-false-的性能边界" aria-label="Permalink to &quot;visible: false 的性能边界&quot;">​</a></h2><p>节点或祖先 <code>visible: false</code> 时，不绘制、不命中，也不会为其解析图片路径、启动 WIC 解码、请求缩略图或调用同步 <code>content</code> 绘制回调。用它控制图片预览可以避免隐藏内容的首次加载。</p><p>节点仍保留在保留式视图树中，拓扑、状态、已解析属性和之前缓存的 GPU 位图不会因隐藏立即删除，便于恢复显示。属性表达式和依赖更新仍可能运行；已排队的共享缩略图任务可能完成，隐藏不会取消其他节点也在使用的任务。<code>opacity: 0</code> 不提供同等的资源加载门控。</p><p>Agent 可从个性化 schema 读取 <code>matches</code>、<code>visibility</code>、<code>file_tooltip</code>、<code>file_tooltip_policy</code>、<code>file_tooltip_inputs</code> 和 <code>external_images</code>。收纳盒快照的 <code>file_tooltip</code> 返回最近提示上下文下求值的策略摘要，不额外输出提示路径或文本。修改应以所检查依赖的 <code>FileTooltip</code> 增量为准，并保持测量与绘制参数一致。</p>`,28)]))}const m=o(c,[["render",s]]);export{u as __pageData,m as default};
